"""Build the mosquito's source-synchronized, offline-ready review player."""
from pathlib import Path
from html import escape
import json,re
OUT=Path(__file__).resolve().parent/'integrated'
s=json.loads((OUT/'shot.json').read_text());e=lambda x:escape(str(x),quote=True)
template=(OUT.parents[1]/'fan/integrated/index.html').read_text()
style=re.search(r'<style>(.*?)</style>',template,re.S).group(1)
cards=[]
for k,f in enumerate(s['keys'],1):
 t=s['frames'][f]['source_time'];cards.append(f'<figure><div class="pair"><img src="source-{k:02d}.jpg" alt="Archive source {t:.3f} seconds"><img src="key-{k:02d}.png" alt="Assembled cartoon key {k}"></div><figcaption>Key {k} · source {t:.3f} s · frame {f}</figcaption></figure>')
note=s.get('review_note','Final playback review remains pending.')
badge='PLACEMENT REPAIR PENDING' if s.get('review_status')=='late_registration_repair_pending' else 'ASSEMBLED REVIEW COPY'
fit=s['mask_fit']
reviews=' · '.join(f'<a href="{x.name}">Independent review {i}</a>' for i,x in enumerate(sorted(OUT.glob('review-v*.json')),1))
page=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mosquito · assembled review · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>{style}</style><body><main class="wrap"><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../wave2-keyframes.html">All ten subjects</a><a href="../index.html">Earlier isolated keys</a></nav><h1>Mosquito on skin.</h1><p class="meta">{s['frame_count']} rendered frames · {s['fps']} fps · {len(s['keys'])} full-scene keys · {s['duration']:.3f} seconds</p><p><span class="badge">{badge}</span></p><div class="player"><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video></div><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Cartoon</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Source beside cartoon</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Source</button></div><p class="meta">The mosquito stays on the skin while its abdomen changes pitch. A single skin surface and hair drawing receive source-measured camera translation. {e(note)}</p><h2>Eight moments, fully assembled.</h2><p class="meta">Archive at left; the same source instant as a cartoon at right.</p><section class="keys">{''.join(cards)}</section><details><summary>References and review</summary><p>Quick, Draw! key {e(s['design']['key_id'])}. Same original eight strokes, in native left-facing orientation to match the footage. The earlier isolated preview was mirrored. Quick, Draw! contributors / Google Creative Lab, CC BY 4.0. Skin and hairs drawn once by agent against the source.</p><p>Archive: <a href="{e(s['source']['page_url'])}">Insects</a>, clip-relative {s['source']['interval_seconds'][0]:.3f}–{s['source']['interval_seconds'][1]:.3f} s. Archive rights were not supplied in the candidate manifest.</p><p>SAM 2.1 source masks were run upstream; {s['source_segmentation']['frames']} source mask frames and their exact provenance are retained. Filled drawing vs source-mask IoU: mean {fit['mean']:.3f}, minimum {fit['minimum']:.3f}. The source-pose mask-fit bar is {'met' if fit['pass'] else 'not met'} (mean≥0.65, minimum≥0.45). Thin appendages are incompletely segmented. Predicted SAM confidence is not measured cartoon fit.</p><p><a href="shot.json">Timeline and observations</a> · <a href="assembly-checks.json">Assembly checks</a> · <a href="source-track.json">Source SAM masks</a> · <a href="design.png">Original doodle</a> · <a href="traced.json">Character traces</a> · {reviews}</p><p>Recognition classifier and independent normal-speed playback remain unrun. Authored contact holds have not passed the independent four-interval contact test. No training ran. This is not a release-approved result.</p></details><footer><a href="cartoon.mp4" download>Download cartoon</a> · <a href="comparison.mp4" download>Download synchronized comparison</a></footer></main><script>
const v=document.querySelector('#film');for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{{const t=v.currentTime;const playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{{v.currentTime=Math.min(t,v.duration||0);if(playing)v.play().catch(()=>{{}})}},{{once:true}});v.load()}});
</script></html>'''
(OUT/'index.html').write_text(page)
print(OUT/'index.html')
